/**
 * A tiny, dependency-free music synthesizer: writes 16-bit mono WAV.
 * Music made here is original and generated by code, so it is free to use anywhere.
 *
 * genres:
 *   ragtime  — stride piano (oom-pah bass + chords), syncopated melody, brushed backbeat.
 *              For Rubber Hose / 1930s styles.
 *   lofi     — mellow 7th chords, soft kick + hat, slow. For calm / cozy styles.
 */
const SR = 32000;

function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let r = Math.imul(a ^ (a >>> 15), 1 | a);
    r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}
const hz = (midi) => 440 * Math.pow(2, (midi - 69) / 12);

class Track {
  constructor(seconds) {
    this.buf = new Float32Array(Math.ceil(seconds * SR));
  }
  /** piano-ish tone: a few harmonics, fast attack, exponential decay; `detune` for honky-tonk */
  piano(t, midi, dur, vel = 0.3, detune = 0.004) {
    const f = hz(midi);
    const start = Math.floor(t * SR);
    const n = Math.floor((dur + 0.4) * SR);
    for (let i = 0; i < n && start + i < this.buf.length; i++) {
      const s = i / SR;
      const env = Math.min(1, s / 0.004) * Math.exp(-s * (2.2 + midi / 40)) * (s > dur ? Math.exp(-(s - dur) * 12) : 1);
      let v = 0;
      for (const [h, a] of [[1, 1], [2, 0.45], [3, 0.22], [4, 0.1]]) {
        v += a * (Math.sin(2 * Math.PI * f * h * s) + Math.sin(2 * Math.PI * f * h * (1 + detune) * s)) * 0.5;
      }
      this.buf[start + i] += v * env * vel;
    }
  }
  /** soft sine bass / tuba */
  bass(t, midi, dur, vel = 0.35) {
    const f = hz(midi);
    const start = Math.floor(t * SR);
    const n = Math.floor(dur * SR);
    for (let i = 0; i < n && start + i < this.buf.length; i++) {
      const s = i / SR;
      const env = Math.min(1, s / 0.02) * Math.exp(-s * 3);
      this.buf[start + i] += (Math.sin(2 * Math.PI * f * s) + 0.3 * Math.sin(4 * Math.PI * f * s)) * env * vel;
    }
  }
  /** noise burst: brush / hat / woodblock */
  noise(t, dur, vel, seed, tone = 0) {
    const r = rng(seed);
    const start = Math.floor(t * SR);
    const n = Math.floor(dur * SR);
    let prev = 0;
    for (let i = 0; i < n && start + i < this.buf.length; i++) {
      const s = i / SR;
      let v = r() * 2 - 1;
      if (tone) v = 0.6 * Math.sin(2 * Math.PI * tone * s) + 0.4 * v;
      prev = prev * 0.5 + v * 0.5; // gentle low-pass
      this.buf[start + i] += prev * Math.exp(-s * (tone ? 40 : 25)) * vel;
    }
  }
  kick(t, vel = 0.5) {
    const start = Math.floor(t * SR);
    for (let i = 0; i < 0.25 * SR && start + i < this.buf.length; i++) {
      const s = i / SR;
      this.buf[start + i] += Math.sin(2 * Math.PI * (50 + 90 * Math.exp(-s * 30)) * s) * Math.exp(-s * 12) * vel;
    }
  }
}

// chord tones as MIDI offsets from C4 (60)
const PROGRESSIONS = {
  ragtime: [[0, 4, 7, 12], [9, 13, 16, 19], [2, 6, 9, 12], [7, 11, 14, 17]], // C  A7  D7  G7
  lofi: [[5, 9, 12, 16], [4, 7, 11, 14], [2, 5, 9, 12], [0, 4, 7, 11]],     // Fmaj7 Em7 Dm7 Cmaj7
};

export function compose({ genre = "ragtime", bpm = 120, seconds = 10, seed = 7, key = 0 }) {
  const tr = new Track(seconds + 1);
  const beat = 60 / bpm;
  const bars = Math.ceil(seconds / (beat * 4)) + 1;
  const r = rng(seed);
  const prog = PROGRESSIONS[genre] ?? PROGRESSIONS.ragtime;

  for (let b = 0; b < bars; b++) {
    const chord = prog[b % prog.length].map((n) => n + 60 + key);
    const t0 = b * 4 * beat;
    if (genre === "lofi") {
      chord.forEach((n, i) => tr.piano(t0 + i * 0.03, n - 12, beat * 3.6, 0.09, 0.002));
      tr.bass(t0, chord[0] - 24, beat * 2, 0.3);
      tr.bass(t0 + beat * 2.5, chord[2] - 24, beat * 1.4, 0.22);
      for (let k = 0; k < 4; k++) {
        if (k % 2 === 0) tr.kick(t0 + k * beat, 0.35);
        tr.noise(t0 + (k + 0.5) * beat, 0.05, 0.05, b * 9 + k);
      }
      // a few lazy melody notes
      for (let k = 0; k < 3; k++) if (r() < 0.6) tr.piano(t0 + (k * 1.25 + 0.5) * beat, chord[1 + Math.floor(r() * 3)] + 12, beat, 0.08, 0.001);
    } else {
      // stride left hand: low root, mid chord, low fifth, mid chord
      tr.bass(t0, chord[0] - 24, beat * 0.9);
      tr.piano(t0 + beat, chord[0] - 12, beat * 0.4, 0.07);
      chord.slice(1, 3).forEach((n) => tr.piano(t0 + beat, n - 12, beat * 0.4, 0.07));
      tr.bass(t0 + 2 * beat, chord[2] - 24, beat * 0.9);
      tr.piano(t0 + 3 * beat, chord[0] - 12, beat * 0.4, 0.07);
      chord.slice(1, 3).forEach((n) => tr.piano(t0 + 3 * beat, n - 12, beat * 0.4, 0.07));
      // brushed backbeat + woodblock pickups
      tr.noise(t0 + beat, 0.12, 0.12, b * 4 + 1);
      tr.noise(t0 + 3 * beat, 0.12, 0.12, b * 4 + 3);
      if (r() < 0.5) tr.noise(t0 + 3.5 * beat, 0.05, 0.12, b * 4 + 5, 900);
      // syncopated right-hand melody on eighths
      let last = chord[2] + 12;
      for (let e = 0; e < 8; e++) {
        const syncop = e === 3 || e === 5 ? 0.85 : 0.6;
        if (r() > syncop) continue;
        const pool = [...chord.map((n) => n + 12), chord[0] + 14, chord[0] + 21];
        const n = r() < 0.6 ? pool.reduce((a, c) => (Math.abs(c - last) < Math.abs(a - last) ? c : a)) : pool[Math.floor(r() * pool.length)];
        tr.piano(t0 + e * beat * 0.5, n, beat * 0.45, 0.16);
        last = n;
      }
    }
  }
  // end on the tonic
  const end = seconds - beat * 2;
  if (end > 0) [0, 4, 7, 12].forEach((n) => tr.piano(end, 60 + key + n, beat * 2, 0.12));
  return tr.buf.subarray(0, Math.ceil(seconds * SR));
}

export function wav(samples, sampleRate = SR) {
  let peak = 0;
  for (const v of samples) peak = Math.max(peak, Math.abs(v));
  const g = peak > 0 ? 0.89 / peak : 1;
  const buf = Buffer.alloc(44 + samples.length * 2);
  buf.write("RIFF", 0);
  buf.writeUInt32LE(36 + samples.length * 2, 4);
  buf.write("WAVEfmt ", 8);
  buf.writeUInt32LE(16, 16);
  buf.writeUInt16LE(1, 20);
  buf.writeUInt16LE(1, 22);
  buf.writeUInt32LE(sampleRate, 24);
  buf.writeUInt32LE(sampleRate * 2, 28);
  buf.writeUInt16LE(2, 32);
  buf.writeUInt16LE(16, 34);
  buf.write("data", 36);
  buf.writeUInt32LE(samples.length * 2, 40);
  for (let i = 0; i < samples.length; i++) buf.writeInt16LE(Math.round(Math.max(-1, Math.min(1, samples[i] * g)) * 32767), 44 + i * 2);
  return buf;
}
